{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Procainamide, a close benzamide analogue with a basic diethylaminoethyl side chain, has absolute oral bioavailability of 75–95% in patients, supporting high F for the query's similar benzamide-morpholine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Procainamide administered as a sustained-release tablet showed 79 ± 4% absolute oral bioavailability in normal volunteers, directly relevant to the query's modified-release condition and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Haloperidol, sharing the 4-chlorophenyl and basic amine features, has absolute oral bioavailability of about 65% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Sematilide, another para-substituted benzamide with a basic amine side chain, has absolute oral bioavailability of about 47%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Loperamide has very low oral bioavailability (0.3%), but it is a much larger, highly lipophilic P-gp substrate; its structural and physicochemical differences make this low-F evidence weakly transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small, moderately lipophilic benzamide with a morpholinoethyl side chain. The most transferable experimental evidence—procainamide (75–95%), sustained-release procainamide (79%), sematilide (~47%), and haloperidol (~65%)—all show absolute oral bioavailability well above 20%. The only low-F analogue, loperamide, is much larger, more lipophilic, and a known P-gp substrate, so its poor bioavailability does not transfer to this smaller, less lipophilic molecule. The modified-release condition is consistent with high F, as sustained-release procainamide retained ~79% bioavailability. Therefore, high F (≥20%) is predicted.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself; all evidence comes from analogues with low-to-moderate Morgan similarity.",
    "First-pass metabolism and transporter effects for the query are not directly measured.",
    "Modified-release formulation-specific bioavailability data for the exact query are lacking."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

